import * as T from '../vendor/three.module.js';import {palettePair} from './palette-pair.js';
const r=new T.WebGLRenderer({canvas:document.querySelector('canvas'),antialias:false});r.outputEncoding=T.sRGBEncoding;const scene=new T.Scene();scene.background=new T.Color('#142634');const camera=new T.OrthographicCamera(-6,6,3,-3,.1,100),objects=[],groups=[];let yaw=0;
for(const [i,group] of ['env','char'].entries()){const m=new T.MeshStandardMaterial({color:'#b8b2a2'}),pair=palettePair(m),mesh=new T.Mesh(new T.SphereGeometry(1.2,24,16),m);mesh.position.set(i?2:-2,0,0);mesh.scale.set(1,1.3,.65);scene.add(mesh);objects.push(mesh);groups.push(pair);function update(neutral=false){pair.update(document.querySelector('#'+group+'-lit').value,document.querySelector('#'+group+'-shade').value,document.querySelector('#'+group+'-add').value,neutral);}document.querySelectorAll('[id^='+group+'-]').forEach(e=>e.oninput=()=>update());pair.refresh=update;update();}
document.querySelector('#angle').oninput=e=>{const a=Number(e.target.value)*Math.PI/180;groups.forEach(g=>g.direction.value.set(Math.sin(a),.8,Math.cos(a)));};document.querySelector('#neutral').onclick=()=>groups.forEach(g=>g.refresh(true));document.querySelector('#authored').onclick=()=>groups.forEach(g=>g.refresh());document.querySelector('#bypass').onclick=e=>{const on=e.target.getAttribute('aria-pressed')!=='true';e.target.setAttribute('aria-pressed',on);groups.forEach(g=>g.bypass.value=Number(on));};document.querySelector('#rotate').onclick=()=>objects.forEach(o=>o.rotation.y+=Math.PI/4);document.querySelector('#orbit').onclick=()=>yaw+=Math.PI/4;
function draw(){const c=r.domElement,w=c.clientWidth,h=c.clientHeight;r.setSize(w,h,false);camera.left=-3*w/h;camera.right=3*w/h;camera.updateProjectionMatrix();camera.position.set(Math.sin(yaw)*12,4,Math.cos(yaw)*12);camera.lookAt(0,0,0);r.render(scene,camera);requestAnimationFrame(draw);}draw();window.__pair={r,scene,camera,objects,groups};
